import{_ as o,l as s,o as a,c as l,v as t,p as n,x as r,d as c,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Spectre 缓解与代价","description":"","frontmatter":{"title":"Spectre 缓解与代价","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spectre-mitigations.md","filePath":"cs/spectre-mitigations.md","lastUpdated":1789023840000}'),d={name:"cs/spectre-mitigations.md"};function E(m,e,_,A,u,B){const i=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="spectre-缓解与代价" tabindex="-1">Spectre 缓解与代价 <a class="header-anchor" href="#spectre-缓解与代价" aria-label="Permalink to &quot;Spectre 缓解与代价&quot;">​</a></h1><div class="epigraph"><p>Spectre 用预测执行把秘密打进微结构状态。缓解是隔离、栅栏、间接预测限制——每一刀都有性能账。合同是威胁模型与账单，不是「已彻底消失」。</p><footer>—— Kocher et al., Spectre Attacks, 2019 IEEE S&amp;P；对照[瞬态执行](/cs/transient-exec)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/puf">PUF</a>是制造差异。缺口回到<strong>共享 CPU</strong>：主干瞬态课已给现象。本课收缓解与代价，不给测量密钥的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程隔离不隔离预测器与缓存。缓解：retpoline、IBRS、站点隔离、减共享。缺口是性能与覆盖的清单。</p><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h3><p>站点隔离是软件缓解，与 CPU 微码叠加。</p><p><span class="marginnote">Kocher et al. Spectre。禁止利用步骤。Rowhammer 下一课是 DRAM 物理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照软件栅栏与硬件计数器刷新。账单：系统调用与上下文切换变贵。下一课 Rowhammer。</p>',12)),(a(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E9%A2%84%E6%B5%8B%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20LEAK%5B%22%E5%BE%AE%E7%BB%93%E6%9E%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20MIT%5B%22%E6%A0%85%E6%A0%8F%E4%B8%8E%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20COST%5B%22%E6%80%A7%E8%83%BD%E8%B4%A6%22%5D%0A%20%20MIT%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E4%BB%8D%E8%A6%81%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逻辑正确的程序仍可漏 C。Rowhammer 下一课扰的是 DRAM 比特而不是预测器。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 PoC。Rowhammer 缓解下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PUF 之后回到共享 CPU 泄漏。</li><li>缓解是隔离加栅栏，带性能账。</li><li>不是一次补丁永久关闭。</li><li>下一课 Rowhammer。</li><li>出处：Kocher et al., Spectre；<a href="/cs/transient-exec">transient-exec</a>。</li></ul>',8))])}const P=o(d,[["render",E]]);export{S as __pageData,P as default};
